use std::fs

struct Tree {
    keys: Vec<int>,
    left: Vec<int>,
    right: Vec<int>,
    root: int,
}

impl Tree {
    fn insert(self, x: int) -> bool {
        if self.root < 0 {
            self.keys.push(x)
            self.left.push(-1)
            self.right.push(-1)
            self.root = 0
            return true
        }
        let mut cur = self.root
        loop {
            let k = self.keys[cur as usize]
            if x == k {
                return false
            }
            let next = if x < k { self.left[cur as usize] } else { self.right[cur as usize] }
            if next < 0 {
                let id = self.keys.len() as int
                self.keys.push(x)
                self.left.push(-1)
                self.right.push(-1)
                if x < k {
                    self.left[cur as usize] = id
                } else {
                    self.right[cur as usize] = id
                }
                return true
            }
            cur = next
        }
        true
    }

    fn contains(self, x: int) -> bool {
        let mut cur = self.root
        while cur >= 0 {
            let k = self.keys[cur as usize]
            if x == k {
                return true
            }
            cur = if x < k { self.left[cur as usize] } else { self.right[cur as usize] }
        }
        false
    }

    fn set_child(self, parent: int, old: int, new: int) {
        if parent < 0 {
            self.root = new
        } else if self.left[parent as usize] == old {
            self.left[parent as usize] = new
        } else {
            self.right[parent as usize] = new
        }
    }

    fn delete(self, x: int) -> bool {
        let mut parent = -1
        let mut cur = self.root
        while cur >= 0 {
            let k = self.keys[cur as usize]
            if x == k {
                break
            }
            parent = cur
            cur = if x < k { self.left[cur as usize] } else { self.right[cur as usize] }
        }
        if cur < 0 {
            return false
        }
        let l = self.left[cur as usize]
        let r = self.right[cur as usize]
        if l >= 0 && r >= 0 {
            let mut sp = cur
            let mut s = r
            while self.left[s as usize] >= 0 {
                sp = s
                s = self.left[s as usize]
            }
            self.keys[cur as usize] = self.keys[s as usize]
            let sr = self.right[s as usize]
            self.set_child(sp, s, sr)
        } else if l >= 0 {
            self.set_child(parent, cur, l)
        } else {
            self.set_child(parent, cur, r)
        }
        true
    }

    fn height(self, n: int) -> int {
        if n < 0 {
            return 0
        }
        let a = self.height(self.left[n as usize])
        let b = self.height(self.right[n as usize])
        if a > b { a + 1 } else { b + 1 }
    }

    fn inorder(self) -> string {
        let mut out: Vec<string> = []
        let mut stack: Vec<int> = []
        let mut cur = self.root
        while cur >= 0 || stack.len() > 0 {
            while cur >= 0 {
                stack.push(cur)
                cur = self.left[cur as usize]
            }
            let n = stack.pop().unwrap_or(-1)
            out.push("${self.keys[n as usize]}")
            cur = self.right[n as usize]
        }
        if out.len() == 0 {
            return "<empty>"
        }
        out.join(" ")
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut t = Tree { keys: [], left: [], right: [], root: -1 }
    for line in text.lines() {
        let parts: Vec<string> = line.trim().split(" ").collect()
        let cmd = parts[0]
        if cmd == "insert" {
            let x: int = parts[1].parse().unwrap_or(0)
            println(if t.insert(x) { "ok" } else { "dup" })
        } else if cmd == "contains" {
            let x: int = parts[1].parse().unwrap_or(0)
            println(if t.contains(x) { "yes" } else { "no" })
        } else if cmd == "delete" {
            let x: int = parts[1].parse().unwrap_or(0)
            println(if t.delete(x) { "ok" } else { "missing" })
        } else if cmd == "inorder" {
            println(t.inorder())
        } else if cmd == "height" {
            println("${t.height(t.root)}")
        } else if cmd == "min" || cmd == "max" {
            if t.root < 0 {
                println("empty")
            } else {
                let mut c = t.root
                if cmd == "min" {
                    while t.left[c as usize] >= 0 { c = t.left[c as usize] }
                } else {
                    while t.right[c as usize] >= 0 { c = t.right[c as usize] }
                }
                println("${t.keys[c as usize]}")
            }
        }
    }
}

